// lib/wagmi.ts
import { createConfig, http } from 'wagmi';
import { defineChain } from 'viem';
import { injected } from 'wagmi/connectors';
import { createStorage } from 'wagmi/storage';

// ✅ 定义 Ganache 本地区块链网络
export const ganache = defineChain({
  id: 1337,
  name: 'Ganache Local',
  nativeCurrency: {
    name: 'Ethereum',
    symbol: 'ETH',
    decimals: 18,
  },
  rpcUrls: {
    default: { http: ['http://127.0.0.1:7545'] }, // 你的 Ganache RPC 地址
  },
});

export const config = createConfig({
  chains: [ganache],
  connectors: [
    injected({ shimDisconnect: true }), // ✅ 显式启用 MetaMask 注入式连接器
  ],
  storage: createStorage({
    storage: localStorage, // ✅ 保留登录状态
  }),
  transports: {
    [ganache.id]: http('http://127.0.0.1:7545'),
  },
});
